.hsn-card::before{content:"";position:absolute;inset:0;border-radius:14px;background:repeating-conic-gradient(rgba(192,192,192,0.02) 0% 25%,transparent 0% 50%) 0 0/20px 20px;pointer-events:none}
.hsn-header{display:flex;align-items:center;gap:10px;padding:12px 18px;cursor:pointer;user-select:none;position:relative;z-index:1}
.hsn-snake{font-size:1.2rem;filter:drop-shadow(0 0 4px rgba(192,192,192,0.4))}
.hsn-title{flex:1;color:#c0c0c0;font-size:0.85rem;font-weight:500;letter-spacing:0.1em}
.hsn-page{color:rgba(192,192,210,.5);font-size:0.6rem;letter-spacing:0.08em;font-family:'Courier New',monospace}
.hsn-arrow{color:#6b7280;font-size:0.55rem;transition:transform 0.35s cubic-bezier(0.4,0,0.2,1)}
.hsn-card.open .hsn-arrow{transform:rotate(90deg)}
.hsn-body{max-height:0;overflow:hidden;transition:max-height 0.45s cubic-bezier(0.4,0,0.2,1);position:relative;z-index:1}
.hsn-card.open .hsn-body{max-height:800px}
.hsn-inner{padding:4px 18px 14px}
.hsn-row{display:flex;align-items:center;margin-bottom:4px;gap:8px}
.hsn-label{color:#6b7280;font-size:0.65rem;width:48px;text-align:right;flex-shrink:0}
.hsn-bar{flex:1;height:5px;background:rgba(192,192,192,0.08);border-radius:3px;overflow:hidden}
.hsn-fill{height:100%;border-radius:3px;transition:width 0.5s ease}
.hsn-val{color:#c9d1d9;font-size:0.65rem;width:28px;text-align:right;flex-shrink:0}
.hsn-divider{height:1px;margin:10px 0;background:linear-gradient(90deg,transparent,rgba(192,192,192,0.15),rgba(148,163,184,0.2),rgba(192,192,192,0.15),transparent)}
.hsn-tags{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:4px}
.hsn-tag{font-size:0.6rem;padding:2px 10px;border-radius:10px;border:1px solid rgba(192,192,192,0.12);color:#94a3b8;background:rgba(22,33,62,0.6)}
