.hsn-home{display:flex;justify-content:center;padding:8px 0 4px}
.hsn-home-bar{width:40px;height:3px;border-radius:2px;background:rgba(192,192,192,0.12)}
</style>
<script type="module">
var periodMap={"童年":"育幼院","學生":"台大醫學系","成年":"寧馨婦產科院長"};
var stageDescMap={
  "接近":"重逢試探","動搖":"關係鬆動","確認":"彼此確認",
  "同學":"日常相處","曖昧":"情感交纏","分歧":"命運抉擇",
  "警戒":"戒備觀察","習慣":"慢慢靠近","依附":"深度依賴"
};
function populateCharacterData(){
  var all=getAllVariables();
  var s=_.get(all,'stat_data',{});
  var bars=[
    ['security','安全感',0,'#60a5fa','#93c5fd'],
    ['mask','面具',0,'#a78bfa','#c4b5fd'],
    ['intimacy','親密度',0,'#f472b6','#f9a8d4']
  ];
  bars.forEach(function(b){
    var val=_.get(s,b[1],b[2]);
    var el=$('#hsn-b-'+b[0]);
    var num=$('#hsn-v-'+b[0]);
    if(el.length)el.css({width:val+'%',background:'linear-gradient(90deg,'+b[3]+','+b[4]+')'});
    if(num.length)num.text(val);
  });
  var period=_.get(s,'時期','成年');
  var stage=_.get(s,'階段','');
  $('#hsnPeriodTag').text(period);
  $('#hsnStageTag').text(stage);
  var descs=[];
  if(periodMap[period])descs.push(period+' — '+periodMap[period]);
  if(stageDescMap[stage])descs.push(stage+' — '+stageDescMap[stage]);
  $('#hsnTagDesc').text(descs.join(' · '));
}
/* 頁碼＝機器從樓層算，不讓模型自己填（模型維持不了遞增計數，會亂飄）。
   樓層來源必須是 getCurrentMessageId()（本樓自己的樓層號）——不能用 getLastMessageId()：
   iframe 每次重渲染（重整頁面/重開聊天/換卡）都會重跑本腳本，「誕生時算一次」的定樁假設不成立，
   getLastMessageId 在重渲染時拿到的是當下最新樓 → 所有樓的頁碼全部漂成最新頁。
   第 0 樓開場＝page.000，user 回覆後思年首答（第 2 樓）＝page.001，之後每組對話遞增一，補零三位。取不到樓層就隱藏。 */
function renderPage(){
  try{
    var g=null,scopes=[window,window.parent,window.top];
    for(var i=0;i<scopes.length;i++){try{if(typeof scopes[i].getCurrentMessageId==='function'){g=scopes[i].getCurrentMessageId;break}}catch(_){}}
    if(!g){$('#hsnPage').text('');return}
    var id=Number(g());
    if(!isFinite(id)||id<0){$('#hsnPage').text('');return}
    var n=Math.floor(id/2); /* 樓0開場=page.000，樓2思年首答=page.001 */
    $('#hsnPage').text('page.'+('00'+n).slice(-3));
  }catch(_){$('#hsnPage').text('')}
}
async function init(){
  await waitGlobalInitialized('Mvu');
  populateCharacterData();
  renderPage(); /* 本樓樓層號（getCurrentMessageId）重渲染也不變——頁碼天然定樁，不掛回合事件 */
  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED,function(){populateCharacterData()});
  $('.hsn-header').on('click',function(){$('#hsnCard').toggleClass('open')});
}
$(errorCatched(init));
</script>
