/* 何思年_變量冷卻 — 變化幅度夾持腳本
   每輪每項變數最多 ±3，超出照上限夾回（分數不要給太快）。
   前 2 樓（開場白切換＋自由開場首輪校準）豁免，不然大幅 replace 校準會被夾死。
   簡化版：不搬凍結計數（$cd 會被 Zod schema 剝除），只留硬夾持。 */

(async () => {
  await waitGlobalInitialized('Mvu');

  const VARS = ['安全感', '面具', '親密度']; /* 時期由開場白鎖定，永不經手 */
  const MAX_DELTA = 3;
  const CALIBRATION_FLOOR = 2; /* 樓層 <= 2 視為校準窗，不夾持 */

  function num(value, fallback) {
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
  }

  /* 門檻表鏡射自「何思年 變量結構.js」的階段推導——改門檻時兩處必須同步 */
  function computeStage(data) {
    const 時期 = _.get(data, 'stat_data.時期');
    const 安全感 = num(_.get(data, 'stat_data.安全感'), 0);
    const 面具 = num(_.get(data, 'stat_data.面具'), 100);
    const 親密度 = num(_.get(data, 'stat_data.親密度'), 0);
    if (時期 === '成年') {
      if (親密度 >= 70 && 安全感 >= 40 && 面具 <= 40) return '確認';
      if (親密度 >= 40 && 安全感 >= 25) return '動搖';
      return '接近';
    }
    if (時期 === '學生') {
      if (親密度 >= 65 && 面具 <= 45) return '分歧';
      if (親密度 >= 35 && 安全感 >= 20) return '曖昧';
      return '同學';
    }
    if (親密度 >= 60 && 安全感 >= 50 && 面具 <= 50) return '依附';
    if (安全感 >= 30 && 面具 <= 70) return '習慣';
    return '警戒';
  }

  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (newVariables, oldVariables) => {
    try {
      const lastId = typeof getLastMessageId === 'function' ? Number(getLastMessageId()) : NaN;
      if (Number.isFinite(lastId) && lastId <= CALIBRATION_FLOOR) return;
    } catch (_) { /* 取不到樓層就照常夾持 */ }

    for (const key of VARS) {
      const path = 'stat_data.' + key;
      const oldValue = _.clamp(num(_.get(oldVariables, path), 0), 0, 100);
      const requested = _.clamp(num(_.get(newVariables, path), oldValue), 0, 100);
      const capped = _.clamp(requested, oldValue - MAX_DELTA, oldValue + MAX_DELTA);
      _.set(newVariables, path, capped);
    }
    _.set(newVariables, 'stat_data.階段', computeStage(newVariables));
  });
})();

