    if (intimacy >= 45) return '他留下的痕跡越來越多，還假裝只是剛好。';
    if (Number.isFinite(mask) && mask <= 35) return '那層完美人設鬆了一點；他知道妳看見了。';
    if (safety < 25) return '他把距離拿捏得剛好，近到能照顧妳，遠到不必被看穿。';
    return '他在妳生活裡盤了一小塊位置，暫時沒有要走。';
  }

  function moodFor(state) {
    var stat = state && state.stat || {};
    var now = new Date().getHours();
    if (now >= 0 && now < 6) return 'sleep';
    if ((Number(stat['親密度']) || 0) >= 65) return 'fond';
    if ((Number(stat['安全感']) || 0) < 30) return 'guard';
    return 'idle';
  }

  function savePetState(patch) {
    try {
      var getVars = findApi('getVariables');
      var setVars = findApi('insertOrAssignVariables');
      if (!setVars) return;
      var vars = getVars ? (getVars({ type: 'chat' }) || {}) : {};
      var old = vars['何思年桌寵'] || {};
      setVars({ '何思年桌寵': Object.assign({}, old, patch) }, { type: 'chat' });
    } catch (e) { console.info('[何思年桌寵] v2.6 ready; dialogue=' + dialogueConfig().schemaVersion + '; auto-generation=false; letter-profiles=' + getConnectionProfiles().length + '; user-size=60..180; mobile-safe-area=true; embedded=96-frame-webp; qr=' + QR_SET); }
  }

  function readPetState() {
    try {
      var getVars = findApi('getVariables');
      var vars = getVars ? (getVars({ type: 'chat' }) || {}) : {};
      return vars['何思年桌寵'] || {};
    } catch (e) { return {}; }
  }

  function sameStringList(left, right) {
    var a = Array.isArray(left) ? left : [];
    var b = Array.isArray(right) ? right : [];
    return a.length === b.length && a.every(function(value, index) { return value === b[index]; });
  }

  function hiddenLetterMatches(letter, state) {
    var conditions = letter && letter.conditions || {};
    var stat = state && state.stat || {};
    var safety = Number(stat['安全感']) || 0;
    var intimacy = Number(stat['親密度']) || 0;
    var mask = Number(stat['面具']);
    if (Number.isFinite(Number(conditions.safetyMin)) && safety < Number(conditions.safetyMin)) return false;
    if (Number.isFinite(Number(conditions.intimacyMin)) && intimacy < Number(conditions.intimacyMin)) return false;
    if (Number.isFinite(Number(conditions.maskMax)) && (!Number.isFinite(mask) || mask > Number(conditions.maskMax))) return false;
    return true;
  }

  function availableHiddenLetters(state) {
    var current = state || readState();
    var letters = dialogueConfig().hiddenLetters;
    return (Array.isArray(letters) ? letters : []).filter(function(letter) { return hiddenLetterMatches(letter, current); });
  }

  function syncHiddenLetters() {
    var petState = readPetState();
    var available = availableHiddenLetters(readState());
    var previous = Array.isArray(petState.unlockedHiddenLetterIds) ? petState.unlockedHiddenLetterIds : [];
    var unread = Array.isArray(petState.unreadHiddenLetterIds) ? petState.unreadHiddenLetterIds : [];
    var availableIds = available.map(function(letter) { return letter.id; });
    var unlocked = previous.slice();
    var nextUnread = unread.filter(function(id) { return availableIds.indexOf(id) >= 0; });
    availableIds.forEach(function(id) {
      if (unlocked.indexOf(id) < 0) {
        unlocked.push(id);
        if (nextUnread.indexOf(id) < 0) nextUnread.push(id);
      }
    });
    if (!sameStringList(previous, unlocked) || !sameStringList(unread, nextUnread)) {
      savePetState({ unlockedHiddenLetterIds: unlocked, unreadHiddenLetterIds: nextUnread });
    }
    return { available: available, unlockedIds: unlocked, unreadIds: nextUnread };
  }

  function touchDeskActivity() {
    var at = Date.now();
    savePetState({ lastInteractionAt: at });
    return at;
  }

  function tavernContext() {
    try {
      var tavern = findValue('SillyTavern');
      if (tavern && typeof tavern.getContext === 'function') return tavern.getContext();
      return tavern || null;
    } catch (e) { return null; }
  }

  function getConnectionProfiles() {
    try {
      var context = tavernContext();
      var profiles = context && context.extensionSettings && context.extensionSettings.connectionManager && context.extensionSettings.connectionManager.profiles;
      if (!Array.isArray(profiles)) return [];
      return profiles.map(function(profile) {
        return {
          id: String(profile && profile.id || ''),
          name: String(profile && (profile.name || profile.id) || ''),
          api: String(profile && profile.api || ''),
          model: String(profile && profile.model || '')
        };
      }).filter(function(profile) { return profile.id && profile.name; });
    } catch (e) { return []; }
  }

  function letterMode(state) {
    var mode = state && state.letterMode;
    return mode === 'current' || mode === 'profile' ? mode : 'local';
  }

  function localLetter(state) {
    var stat = state && state.stat || {};
    var intimacy = Number(stat['親密度']) || 0;
    var safety = Number(stat['安全感']) || 0;
    if (intimacy >= 70) return '我本來想把這句包成玩笑。後來覺得算了。妳在的時候，很多事確實比較像生活。';
    if (safety >= 40) return '今天不用表現得很好。妳可以把不好看的那一面先放在這裡，我不急著替它下結論。';
    return '妳不用現在回。我只是替妳留一盞燈，順便證明我這個男閨密還算稱職。';
  }

  function clipText(value, limit) {
    var text = String(value == null ? '' : value).replace(/\s+/g, ' ').trim();
    return text.length > limit ? text.slice(0, limit) + '…' : text;
  }

  function recentConversation(limit) {
    try {
      var context = tavernContext();
      var chat = context && Array.isArray(context.chat) ? context.chat : [];
      return chat.slice(-Math.max(1, limit || 8)).map(function(message) {
        var role = message && message.is_user ? 'Mini' : '何思年';
        return role + '：' + clipText(message && message.mes, 420);
      }).filter(function(line) { return !/[：:]$/.test(line); }).join('\n');
    } catch (e) { return ''; }
  }

  function buildLetterPrompt() {
    var state = readState(), petState = readPetState();
    var stat = state.stat || {};
    var history = Array.isArray(petState.letterHistory) ? petState.letterHistory.slice(-3) : [];
    return [
      '妳是何思年。請寫一封留給 Mini 的私人短箋，只輸出信件正文，不要標題、分析、括號旁白或 Markdown code fence。',
      '語氣：台灣男性自然口語、半開玩笑半認真、溫柔但不說教；可以毒舌或自嘲，但不物化女性、不用商業交易話術、不宣稱自己是 AI。',
      '必須遵守當前時期與關係邊界。童年時期只能是孩子對可信任照顧者的陪伴文字，禁止戀愛或曖昧。',
      '當前狀態：時期 ' + String(stat['時期'] || '成年') + '，階段 ' + phaseName(state) + '，安全感 ' + numberLabel(stat['安全感']) + '，面具 ' + numberLabel(stat['面具']) + '，親密度 ' + numberLabel(stat['親密度']) + '。',
      recentConversation(8) ? '最近對話：\n' + recentConversation(8) : '',
      history.length ? '不要重複最近留下的句子：\n' + history.map(function(item) { return clipText(item && item.text, 180); }).join('\n') : '',
      '長度約 80 至 220 個繁體中文字；像他趁 Mini 沒注意時壓在桌邊的一張紙，不替 Mini 決定感受或行動。'
    ].filter(Boolean).join('\n\n');
  }

  function slashQuote(value) {
    return JSON.stringify(String(value == null ? '' : value)).replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');
  }

  function cleanGeneratedLetter(value) {
    var text = typeof value === 'string' ? value : value && typeof value === 'object' && typeof value.content === 'string' ? value.content : '';
    text = text.trim().replace(/^```(?:markdown|text)?\s*/i, '').replace(/\s*```$/, '').trim();
    if (!text) throw new Error('何思年沒有留下文字；請檢查生成連線後再試一次。');
    return text.slice(0, 2400);
  }

  function saveGeneratedLetter(text, source) {
    var current = readPetState();
    var history = Array.isArray(current.letterHistory) ? current.letterHistory.slice(-11) : [];
    var record = { text: text, source: source, at: new Date().toISOString() };
    history.push(record);
    savePetState({ generatedLetter: text, generatedLetterSource: source, generatedLetterAt: record.at, letterHistory: history, letterUnread: true, letterError: '' });
  }

  async function generateLetter() {
    var petState = readPetState(), mode = letterMode(petState);
    if (mode === 'local') return { text: localLetter(readState()), source: '使用本地信件', generated: false };
    var prompt = buildLetterPrompt();
    var result;
    var source;
    if (mode === 'profile') {
      var profiles = getConnectionProfiles();
      var profile = profiles.find(function(item) { return item.id === String(petState.letterProfileId || ''); });
      if (!profile) throw new Error('找不到指定的連線設定檔。請回到相處設定重新選擇副連線。');
      var slash = findApi('triggerSlash');
      if (!slash) throw new Error('酒館指令沒有接上，無法使用指定副連線。');
      var command = '/profile-genstream profile=' + slashQuote(profile.id) + ' reasoning=false length=600 generating=' + slashQuote('何思年正在寫信……') + ' completed=' + slashQuote('信已擱在桌邊') + ' delay=900 stop=true ' + slashQuote(prompt);
      result = await slash(command);
      source = '指定副連線 · ' + profile.name + (profile.model ? ' · ' + profile.model : '');
    } else {
      var generate = findApi('generate');
      if (generate) {
        result = await generate({ user_input: prompt, should_stream: false, should_silence: true, max_chat_history: 12 });
      } else {
        var quiet = findApi('generateQuietPrompt');
        if (!quiet) throw new Error('找不到酒館生成介面；請確認 TavernHelper 已啟用。');
        result = await quiet({ quietPrompt: prompt, responseLength: 600, removeReasoning: true, trimToSentence: false });
      }
      source = '沿用目前酒館連線';
    }
    var text = cleanGeneratedLetter(result);
    saveGeneratedLetter(text, source);
    return { text: text, source: source, generated: true };
  }

  function poolEntry(name, petState, nowMs) {
    var pool = dialogueConfig().pools[name];
    if (!Array.isArray(pool) || !pool.length) pool = dialogueConfig().pools.default || [];
    if (!pool.length) return { id: 'fallback', text: '妳忙妳的。我在。', mood: 'idle' };
    var slot = Math.abs(Math.floor((Number(nowMs) || Date.now()) / 60000)) % pool.length;
    var entry = pool[slot];
    if (pool.length > 1 && entry.id === petState.lastWhisperId) entry = pool[(slot + 1) % pool.length];
    return { id: entry.id, text: entry.text, mood: entry.mood || 'idle' };
  }

  function isKnockHour(hour) {
    var windowConfig = dialogueConfig().knockWindow || { startHour: 22, endHour: 3 };
    var start = Number(windowConfig.startHour);
    var end = Number(windowConfig.endHour);
    if (start === end) return true;
    return start < end ? hour >= start && hour < end : hour >= start || hour < end;
  }

  function latestConversationAt() {
    try {
      var context = tavernContext();
      var chat = context && Array.isArray(context.chat) ? context.chat : [];
      for (var i = chat.length - 1; i >= 0; i--) {
        var raw = chat[i] && (chat[i].send_date || chat[i].date || chat[i].timestamp);
        var parsed = typeof raw === 'number' ? raw : Date.parse(raw || '');
        if (Number.isFinite(parsed)) return parsed;
      }
    } catch (e) {}
    return 0;
  }

  function letterMood(text, fallback) {
    var value = String(text || '');
    if (/護|別怕|沒走|留下|燈|等妳|回來|休息/.test(value)) return 'guard';
    if (/誤會|玩笑|看我|嘴硬|自戀/.test(value)) return 'tease';
    if (/喜歡|想見|靠近|位置|捨不得|在乎|想要妳在/.test(value)) return 'fond';
    return fallback || 'fond';
  }

  function letterExcerptEntry(petState) {
    var config = dialogueConfig().excerpt || {};
    if (!petState.generatedLetter || !petState.letterReadAt || petState.letterUnread === true) return null;
    return {
      id: 'letter-excerpt-' + String(petState.generatedLetterAt || petState.letterReadAt || ''),
      kind: 'letter-excerpt',
      label: config.label || '信件讀後摘句',
      text: String(config.prefix || '') + clipText(petState.generatedLetter, Number(config.maxChars) || 46),
      mood: letterMood(petState.generatedLetter, 'fond'),
      action: 'letters'
    };
  }

  function chooseContextWhisper(options) {
    var settings = options || {};
    var nowMs = Number(settings.nowMs) || Date.now();
    var hour = Number.isFinite(Number(settings.hour)) ? Number(settings.hour) : new Date(nowMs).getHours();
    var state = readState();
    var petState = readPetState();
    var hidden = syncHiddenLetters();
    var forceKind = String(settings.forceKind || '');

    if (!forceKind || forceKind === 'unread') {
      if (petState.letterUnread === true && petState.generatedLetter) {
        var reminder = poolEntry('letterReminder', petState, nowMs);
        reminder.kind = 'letter-reminder';
        reminder.action = 'letters';
        return reminder;
      }
      if (hidden.unreadIds.length) {
        var hiddenId = hidden.unreadIds[0];
        var hiddenLetter = hidden.available.find(function(letter) { return letter.id === hiddenId; });
        var hiddenReminder = poolEntry('letterReminder', petState, nowMs);
        hiddenReminder.kind = 'hidden-letter-reminder';
        hiddenReminder.text = hiddenLetter ? '桌邊多了一封〈' + hiddenLetter.title + '〉。要拆嗎？' : hiddenReminder.text;
        hiddenReminder.action = 'hidden:' + hiddenId;
        hiddenReminder.mood = hiddenLetter && hiddenLetter.mood || hiddenReminder.mood;
        return hiddenReminder;
      }
      if (forceKind === 'unread') return null;
    }

    if (forceKind === 'knock') {
      if (!isKnockHour(hour)) return null;
      var knock = poolEntry('knock', petState, nowMs);
      knock.kind = 'night-knock';
      knock.action = 'home';
      return knock;
    }

    if (forceKind === 'excerpt') return letterExcerptEntry(petState);

    var lastActivity = Math.max(Number(petState.lastInteractionAt) || 0, latestConversationAt(), deskRuntimeStartedAt);
    if (nowMs - lastActivity >= Number(dialogueConfig().cooldowns.inactivityMs || 1200000)) {
      var inactive = poolEntry('inactive', petState, nowMs);
      inactive.kind = 'inactive';
      inactive.action = 'home';
      return inactive;
    }
    if ((Number(state.stat['親密度']) || 0) >= 65) {
      var fond = poolEntry('fond', petState, nowMs);
      fond.kind = 'relationship'; fond.action = 'status'; return fond;
    }
    if ((Number(state.stat['安全感']) || 0) < 30) {
      var guard = poolEntry('guard', petState, nowMs);
      guard.kind = 'relationship'; guard.action = 'status'; return guard;
    }
    if (isKnockHour(hour)) {
      var night = poolEntry('night', petState, nowMs);
      night.kind = 'night'; night.action = 'home'; return night;
    }
    if (hour >= 6 && hour < 11) {
      var morning = poolEntry('morning', petState, nowMs);
      morning.kind = 'morning'; morning.action = 'home'; return morning;
    }
    var excerpt = letterExcerptEntry(petState);
    if (excerpt && settings.preferExcerpt === true) return excerpt;
    var ordinary = poolEntry('default', petState, nowMs);
    ordinary.kind = 'context'; ordinary.action = 'home'; return ordinary;
  }

  function showWhisper(entry, options) {
    if (!entry || !entry.text) return null;
    var root = doc.getElementById(ROOT_ID);
    var bubble = root && root.querySelector('.hsnr-pet-whisper');
    if (!bubble) return null;
    var settings = options || {};
    bubble.textContent = entry.text;
    bubble.setAttribute('data-whisper-action', entry.action || 'home');
    bubble.setAttribute('data-whisper-kind', entry.kind || 'context');
    bubble.classList.add('hsnr-visible');
    root.setAttribute('data-last-whisper-id', entry.id || '');
    host.clearTimeout(dialogueRuntime.hide);
    dialogueRuntime.hide = host.setTimeout(function() {
      if (bubble) bubble.classList.remove('hsnr-visible');
    }, Number(settings.visibleMs) || Number(dialogueConfig().cooldowns.visibleMs) || 9000);
    var at = Number(settings.nowMs) || Date.now();
    var patch = { lastWhisperAt: at, lastWhisperId: entry.id || '', lastWhisperKind: entry.kind || 'context' };
    if (entry.kind === 'night-knock') patch.lastKnockAt = at;
    savePetState(patch);
    setPortrait(entry.mood || 'blink', { once: true, returnTo: moodFor(readState()) });
    return entry;
