  function reducedMotion() {
    try { return Boolean(host.matchMedia && host.matchMedia('(prefers-reduced-motion: reduce)').matches); }
    catch (e) { return false; }
  }

  function requestFrame(callback) {
    if (typeof host.requestAnimationFrame === 'function') return host.requestAnimationFrame(callback);
    return host.setTimeout(function() { callback(Date.now()); }, 33);
  }

  function cancelFrame(handle) {
    if (!handle) return;
    if (typeof host.cancelAnimationFrame === 'function') host.cancelAnimationFrame(handle);
    else host.clearTimeout(handle);
  }

  function spriteSequence(name) {
    return SPRITE_ATLAS.sequences[name] || SPRITE_ATLAS.sequences.idle;
  }

  function renderSpriteFrame() {
    var root = doc.getElementById(ROOT_ID);
    if (!root) return;
    var sprite = root.querySelector('.hsnr-pet-sprite');
    if (!sprite) return;
    var sequence = spriteSequence(spriteAnimation.name);
    var frame = sequence.frames[Math.min(spriteAnimation.frame, sequence.frames.length - 1)] || 0;
    var x = SPRITE_ATLAS.columns > 1 ? frame * 100 / (SPRITE_ATLAS.columns - 1) : 0;
    var y = SPRITE_ATLAS.rows > 1 ? sequence.row * 100 / (SPRITE_ATLAS.rows - 1) : 0;
    sprite.style.backgroundPosition = x + '% ' + y + '%';
    root.setAttribute('data-sprite-sequence', spriteAnimation.name);
    root.setAttribute('data-sprite-frame', String(frame));
  }

  function spriteTick(timestamp) {
    spriteAnimation.raf = 0;
    if (!alive() || reducedMotion()) return;
    var sequence = spriteSequence(spriteAnimation.name);
    var interval = 1000 / Math.max(1, sequence.fps || 4);
    if (!spriteAnimation.lastAt) spriteAnimation.lastAt = timestamp;
    if (timestamp - spriteAnimation.lastAt >= interval) {
      spriteAnimation.lastAt = timestamp;
      spriteAnimation.frame += 1;
      if (spriteAnimation.frame >= sequence.frames.length) {
        if (sequence.loop && !spriteAnimation.once) spriteAnimation.frame = 0;
        else {
          setSpriteSequence(spriteAnimation.returnTo || moodFor(readState()));
          return;
        }
      }
      renderSpriteFrame();
    }
    spriteAnimation.raf = requestFrame(spriteTick);
  }

  function setSpriteSequence(name, options) {
    var sequenceName = SPRITE_ATLAS.sequences[name] ? name : 'idle';
    var settings = options || {};
    cancelFrame(spriteAnimation.raf);
    spriteAnimation.name = sequenceName;
    spriteAnimation.frame = 0;
    spriteAnimation.lastAt = 0;
    spriteAnimation.once = settings.once === true;
    spriteAnimation.returnTo = settings.returnTo || moodFor(readState());
    renderSpriteFrame();
    if (!reducedMotion()) spriteAnimation.raf = requestFrame(spriteTick);
  }

  function setPortrait(mood, options) {
    var root = doc.getElementById(ROOT_ID);
    if (!root) return;
    var portrait = root.querySelector('.hsnr-pet-portrait');
    if (!portrait) return;
    var sprite = portrait.querySelector('.hsnr-pet-sprite');
    if (!sprite) {
      portrait.innerHTML = '';
      sprite = doc.createElement('span');
      sprite.className = 'hsnr-pet-sprite';
      sprite.setAttribute('aria-hidden', 'true');
      sprite.style.backgroundImage = 'url("' + SPRITE_SHEET_URL + '")';
      portrait.appendChild(sprite);
    }
    setSpriteSequence(mood, options);
  }

  function viewportBox() {
    var viewport = host.visualViewport;
    var left = viewport && Number.isFinite(viewport.offsetLeft) ? viewport.offsetLeft : 0;
    var top = viewport && Number.isFinite(viewport.offsetTop) ? viewport.offsetTop : 0;
    var width = viewport && Number.isFinite(viewport.width) ? viewport.width : (host.innerWidth || doc.documentElement.clientWidth || 0);
    var height = viewport && Number.isFinite(viewport.height) ? viewport.height : (host.innerHeight || doc.documentElement.clientHeight || 0);
    return { left: left, top: top, right: left + width, bottom: top + height, width: width, height: height };
  }

  function mobileLayout() {
    return viewportBox().width <= 1000;
  }

  function clampPetSizePercent(value) {
    var numeric = Number(value);
    if (!Number.isFinite(numeric)) numeric = 100;
    return Math.max(60, Math.min(180, Math.round(numeric / 10) * 10));
  }

  function petSizePercent(state) {
    var petState = state || readPetState();
    return clampPetSizePercent(mobileLayout() ? petState.sizeMobile : petState.sizeDesktop);
  }

  function applyPetSize(value, persist) {
    var percent = clampPetSizePercent(value);
    var root = doc.getElementById(ROOT_ID);
    if (root) {
      var baseSize = mobileLayout() ? 104 : 128;
      root.style.setProperty('--hsnr-pet-size', (baseSize * percent / 100) + 'px');
      root.setAttribute('data-pet-size-percent', String(percent));
    }
    if (persist === true) {
      var patch = {};
      patch[mobileLayout() ? 'sizeMobile' : 'sizeDesktop'] = percent;
      savePetState(patch);
    }
    return percent;
  }

  function petBounds(root) {
    var viewport = viewportBox();
    var margin = viewport.width <= 1000 ? 10 : 18;
    var safeBottom = viewport.bottom - margin;
    var composer = doc.getElementById('form_sheld');
    if (composer) {
      var rect = composer.getBoundingClientRect();
      if (rect.height > 0 && rect.top > viewport.top && rect.top < viewport.bottom) safeBottom = Math.min(safeBottom, rect.top - margin);
    }
    var width = root.offsetWidth || (viewport.width <= 1000 ? 104 : 128);
    var height = root.offsetHeight || (viewport.width <= 1000 ? 104 : 128);
    var minX = viewport.left + margin;
    var minY = viewport.top + margin;
    return {
      minX: minX,
      minY: minY,
      maxX: Math.max(minX, viewport.right - width - margin),
      maxY: Math.max(minY, safeBottom - height)
    };
  }

  function clampPet(root, x, y) {
    var bounds = petBounds(root);
    return {
      x: Math.max(bounds.minX, Math.min(bounds.maxX, Number.isFinite(x) ? x : bounds.maxX)),
      y: Math.max(bounds.minY, Math.min(bounds.maxY, Number.isFinite(y) ? y : bounds.maxY))
    };
  }

  function syncPetLayout() {
    layoutState.frame = 0;
    var root = doc.getElementById(ROOT_ID);
    if (!root) return;
    applyPetSize(petSizePercent(readPetState()), false);
    var rect = root.getBoundingClientRect();
    var state = readPetState();
    var desiredX = Number.isFinite(state.x) ? state.x : rect.left;
    var desiredY = Number.isFinite(state.y) ? state.y : rect.top;
    var point = clampPet(root, desiredX, desiredY);
    root.style.left = Math.round(point.x) + 'px';
    root.style.top = Math.round(point.y) + 'px';
    root.style.right = 'auto';
  }

  function schedulePetLayout() {
    if (layoutState.frame) return;
    layoutState.frame = requestFrame(syncPetLayout);
  }

  function clearPetLayout() {
    cancelFrame(layoutState.frame);
    layoutState.frame = 0;
    if (layoutState.observer) layoutState.observer.disconnect();
    if (layoutState.mutationObserver) layoutState.mutationObserver.disconnect();
    layoutState.observer = null;
    layoutState.mutationObserver = null;
    layoutState.disposers.splice(0).forEach(function(dispose) { try { dispose(); } catch (e) {} });
  }

  function watchPetLayout() {
    clearPetLayout();
    function listen(target, eventName) {
      if (!target || typeof target.addEventListener !== 'function') return;
      target.addEventListener(eventName, schedulePetLayout, { passive: true });
      layoutState.disposers.push(function() { target.removeEventListener(eventName, schedulePetLayout); });
    }
    listen(host, 'resize');
    listen(host, 'orientationchange');
    listen(host.visualViewport, 'resize');
    listen(host.visualViewport, 'scroll');
    if (typeof host.ResizeObserver === 'function') {
      layoutState.observer = new host.ResizeObserver(schedulePetLayout);
      var composer = doc.getElementById('form_sheld');
      if (composer) layoutState.observer.observe(composer);
    }
    if (typeof host.MutationObserver === 'function') {
      layoutState.mutationObserver = new host.MutationObserver(function() {
        var composer = doc.getElementById('form_sheld');
        if (composer && layoutState.observer) layoutState.observer.observe(composer);
        schedulePetLayout();
      });
      layoutState.mutationObserver.observe(doc.body, { childList: true, subtree: true });
    }
    schedulePetLayout();
  }

  function mountPet() {
    stopWhisperScheduler();
    var existing = doc.getElementById(ROOT_ID);
    if (existing) existing.remove();
    ensureStyle();
    var state = readPetState();
    var root = doc.createElement('div');
    root.id = ROOT_ID;
    root.setAttribute('data-hesinian-pet', 'v2');
    root.setAttribute('data-sprite-atlas', '8x12');
    if (state.night === true) root.classList.add('hsnr-night');
    root.innerHTML = '<button class="hsnr-pet-whisper" type="button" data-whisper-action="home" aria-live="polite">妳忙妳的。我在。</button><button class="hsnr-pet-orb" type="button" aria-label="打開何思年桌寵"><span class="hsnr-pet-portrait"></span></button>';
    doc.body.appendChild(root);
    var initialWhisper = chooseContextWhisper({ nowMs: Date.now() });
    if (initialWhisper) {
      var initialBubble = root.querySelector('.hsnr-pet-whisper');
      initialBubble.textContent = initialWhisper.text;
      initialBubble.setAttribute('data-whisper-action', initialWhisper.action || 'home');
      initialBubble.setAttribute('data-whisper-kind', initialWhisper.kind || 'context');
    }
    applyPetSize(petSizePercent(state), false);
    setPortrait(moodFor(readState()));
    var initial = clampPet(root, state.x, state.y);
    root.style.left = Math.round(initial.x) + 'px';
    root.style.top = Math.round(initial.y) + 'px';
    root.style.right = 'auto';
    watchPetLayout();
    startWhisperScheduler();

    var button = root.querySelector('.hsnr-pet-orb');
    var whisper = root.querySelector('.hsnr-pet-whisper');
    whisper.addEventListener('click', function(event) {
      event.preventDefault();
      event.stopPropagation();
      touchDeskActivity();
      var action = whisper.getAttribute('data-whisper-action') || 'home';
      whisper.classList.remove('hsnr-visible');
      if (action.indexOf('hidden:') === 0) openHiddenLetter(action.slice(7));
      else openPet(action);
    });
    var drag = null;
    button.addEventListener('pointerdown', function(event) {
      touchDeskActivity();
      drag = { id: event.pointerId, sx: event.clientX, sy: event.clientY, x: root.getBoundingClientRect().left, y: root.getBoundingClientRect().top, moved: false, sequence: '' };
      setPortrait('blink', { once: true, returnTo: moodFor(readState()) });
      try { button.setPointerCapture(event.pointerId); } catch (e) {}
    });
    button.addEventListener('pointermove', function(event) {
      if (!drag || drag.id !== event.pointerId) return;
      var dx = event.clientX - drag.sx, dy = event.clientY - drag.sy;
      if (Math.abs(dx) + Math.abs(dy) > 5) drag.moved = true;
      if (!drag.moved) return;
      var walking = dx < 0 ? 'walkLeft' : 'walkRight';
      if (drag.sequence !== walking) { drag.sequence = walking; setPortrait(walking); }
      var point = clampPet(root, drag.x + dx, drag.y + dy);
      root.style.left = point.x + 'px'; root.style.top = point.y + 'px'; root.style.right = 'auto';
    });
    function finishDrag(event, cancelled) {
      if (!drag || drag.id !== event.pointerId) return;
      var moved = drag.moved; drag = null;
      if (cancelled) { setPortrait(moodFor(readState())); return; }
      if (moved) {
        var rect = root.getBoundingClientRect();
        savePetState({ x: Math.round(rect.left), y: Math.round(rect.top) });
        setPortrait('turn', { once: true, returnTo: moodFor(readState()) });
      } else {
        setPortrait('tease', { once: true, returnTo: moodFor(readState()) });
        openPet('home');
      }
    }
    button.addEventListener('pointerup', function(event) { finishDrag(event, false); });
    button.addEventListener('pointercancel', function(event) { finishDrag(event, true); });
  }

  function modalShell(title, subtitle) {
    touchDeskActivity();
    var old = doc.getElementById(MODAL_ID);
    if (old) old.remove();
    var overlay = doc.createElement('div');
    overlay.id = MODAL_ID;
    overlay.innerHTML = '<section class="hsnr-modal" role="dialog" aria-modal="true" aria-labelledby="hsnr-modal-title"><header class="hsnr-head"><div><p class="hsnr-eyebrow">WHITE SNAKE · DESK LIGHT</p><h2 class="hsnr-title" id="hsnr-modal-title">' + escapeHtml(title) + '</h2><p class="hsnr-sub">' + escapeHtml(subtitle || '') + '</p></div><button class="hsnr-close" type="button" aria-label="關閉">✕</button></header><div class="hsnr-body"></div></section>';
    var closeButton = overlay.querySelector('.hsnr-close');
    closeButton.addEventListener('click', closePet);
    overlay.addEventListener('pointerdown', function(event) { if (event.target === overlay) closePet(); });
    overlay.addEventListener('keydown', function(event) {
      if (event.key === 'Escape') { event.preventDefault(); closePet(); }
    });
    doc.body.appendChild(overlay);
    try { closeButton.focus(); } catch (e) {}
    return overlay.querySelector('.hsnr-body');
  }

  function closePet() {
    var modal = doc.getElementById(MODAL_ID);
    if (modal) modal.remove();
    setPortrait(moodFor(readState()));
    try {
      var orb = doc.querySelector('#' + ROOT_ID + ' .hsnr-pet-orb');
      if (orb) orb.focus();
    } catch (e) {}
  }

  function bindActions(root) {
    Array.from(root.querySelectorAll('[data-page]')).forEach(function(button) {
      button.addEventListener('click', function() { openPet(button.getAttribute('data-page')); });
    });
  }

  function openHome() {
    var state = readState(), stat = state.stat || {};
    var body = modalShell('何思年', relationLine(state));
    body.innerHTML = '<div class="hsnr-hero"><div class="hsnr-copy">他沒有住進妳的桌面，只是把一盞燈和幾句沒說出口的話留在這裡。點信件可以讀本地字條，也可以明確選擇酒館連線或 Connection Profile 生成；所有結果都只留在桌邊。<br><br><strong>目前關係：</strong>' + escapeHtml(phaseName(state)) + '</div><div class="hsnr-vitals"><div class="hsnr-vital"><span>時期</span><strong>' + escapeHtml(stat['時期'] || '成年') + '</strong></div><div class="hsnr-vital"><span>安全感</span><strong>' + numberLabel(stat['安全感']) + '</strong></div><div class="hsnr-vital"><span>面具</span><strong>' + numberLabel(stat['面具']) + '</strong></div><div class="hsnr-vital"><span>親密度</span><strong>' + numberLabel(stat['親密度']) + '</strong></div></div></div><div class="hsnr-actions"><button class="hsnr-btn primary" data-page="letters">何思年的來信<small>有些話，他比較適合寫下來。</small></button><button class="hsnr-btn" data-page="status">我們現在算什麼<small>只讀時期、安全感、面具與親密度。</small></button><button class="hsnr-btn" data-page="settings">相處設定<small>信件來源、尺寸、夜間與位置。</small></button><button class="hsnr-btn" data-page="diagnostics">哪裡斷線了<small>直接告訴妳怎麼救。</small></button></div>';
    bindActions(body);
  }

  function openStatus() {
    var state = readState(), stat = state.stat || {};
    var body = modalShell('我們現在算什麼', relationLine(state));
    body.innerHTML = '<div class="hsnr-vitals"><div class="hsnr-vital"><span>時期／階段</span><strong>' + escapeHtml(stat['時期'] || '成年') + ' ／ ' + escapeHtml(phaseName(state)) + '</strong></div><div class="hsnr-vital"><span>安全感</span><strong>' + numberLabel(stat['安全感']) + '</strong></div><div class="hsnr-vital"><span>面具</span><strong>' + numberLabel(stat['面具']) + '</strong></div><div class="hsnr-vital"><span>親密度</span><strong>' + numberLabel(stat['親密度']) + '</strong></div></div><div class="hsnr-rule">這裡只讀取原卡 MVU，不會從桌寵反寫關係數值，也不會把信件生成結果塞進角色提示詞。</div><div class="hsnr-actions"><button class="hsnr-btn" data-page="home">返回</button></div>';
    bindActions(body);
  }

  function openHiddenLetter(id) {
    var letter = availableHiddenLetters(readState()).find(function(item) { return item.id === id; });
    if (!letter) return showError('這封藏信的條件還沒有成立；它不會被提前劇透。');
    var petState = readPetState();
    var unread = (Array.isArray(petState.unreadHiddenLetterIds) ? petState.unreadHiddenLetterIds : []).filter(function(item) { return item !== id; });
    var readAt = new Date().toISOString();
    savePetState({ unreadHiddenLetterIds: unread, letterReadAt: readAt, lastReadLetterId: id, lastReadLetterText: letter.text });
    setPortrait(letter.mood || letterMood(letter.text, 'fond'));
    var body = modalShell(letter.title, '這封信只由關係與共同事件解鎖，沒有呼叫模型。');
    body.innerHTML = '<div class="hsnr-copy">' + escapeHtml(letter.text).replace(/\n/g, '<br>') + '<br><br>—— 何思年</div><div class="hsnr-note">本地藏信 · 零生成 · 已記為讀過。信的解鎖條件只讀 MVU，不會直接改變任何關係數值。</div><div class="hsnr-actions"><button class="hsnr-btn" data-page="letters">回到信匣</button><button class="hsnr-btn" data-page="home">收起來</button></div>';
    bindActions(body);
  }

  function openLetters() {
    var state = readState();
    var hiddenState = syncHiddenLetters();
    var petState = readPetState();
    var mode = letterMode(petState);
    var line = petState.generatedLetter || localLetter(state);
    var source = petState.generatedLetter ? (petState.generatedLetterSource || '已保存的書信') : '使用本地信件';
    var canGenerate = mode !== 'local';
    var readAt = new Date().toISOString();
    if (petState.generatedLetter) {
      savePetState({ letterUnread: false, letterReadAt: readAt, lastReadLetterText: petState.generatedLetter });
      petState.letterUnread = false;
      petState.letterReadAt = readAt;
    }
    setPortrait(letterMood(line, 'fond'));
    var hiddenHtml = hiddenState.available.length ? '<div class="hsnr-section-title" style="margin-top:20px"><h3>藏在桌邊的信</h3><p>隨關係與共同事件解鎖</p></div><div class="hsnr-letter-list">' + hiddenState.available.map(function(letter) {
      var unread = hiddenState.unreadIds.indexOf(letter.id) >= 0;
      return '<button class="hsnr-btn" type="button" data-hidden-letter="' + escapeHtml(letter.id) + '"' + (unread ? ' aria-current="true"' : '') + '>' + (unread ? '● ' : '') + escapeHtml(letter.title) + '<small>' + (unread ? '新解鎖，還沒拆。' : '已解鎖，可重讀。') + '</small></button>';
    }).join('') + '</div>' : '';
    var body = modalShell('何思年的來信', '信紙還有餘溫；他只肯把沒說出口的話留在這裡。');
    body.innerHTML = '<div class="hsnr-copy">' + escapeHtml(line).replace(/\n/g, '<br>') + '<br><br>—— 何思年</div><div class="hsnr-note">書信來源：' + escapeHtml(source) + (mode === 'local' ? '<br>目前使用不耗生成的本地字條；藏信也全部在本機解鎖。' : '<br>生成只回到這個 HTML，不會新增聊天樓層。') + '</div>' + hiddenHtml + '<div id="hsnr-letter-error" class="hsnr-error" hidden></div><div class="hsnr-actions">' + (canGenerate ? '<button class="hsnr-btn primary" id="hsnr-generate-letter">讓何思年再留一封</button><button class="hsnr-btn" id="hsnr-generate-desk-line">叫他在桌邊說一句<small>會使用所選連線並消耗一次生成；只顯示氣泡，不送聊天。</small></button>' : '') + '<button class="hsnr-btn" data-page="settings">書信與氣泡設定</button><button class="hsnr-btn" data-page="home">收起來</button></div>';
    bindActions(body);
    Array.from(body.querySelectorAll('[data-hidden-letter]')).forEach(function(button) {
      button.addEventListener('click', function() { openHiddenLetter(button.getAttribute('data-hidden-letter')); });
    });
    var generateButton = body.querySelector('#hsnr-generate-letter');
    if (generateButton) generateButton.addEventListener('click', async function() {
      var error = body.querySelector('#hsnr-letter-error');
      generateButton.disabled = true;
      generateButton.textContent = '紙上正慢慢多出字……';
      error.hidden = true;
      try {
        await generateLetter();
        setPortrait('fond');
        openLetters();
      } catch (e) {
        var message = e && e.message ? e.message : '書信生成失敗。';
        savePetState({ letterError: message });
        error.textContent = message + ' 原本的本地信件仍可閱讀，沒有送出任何聊天訊息。';
        error.hidden = false;
        generateButton.disabled = false;
        generateButton.textContent = '再試一次';
      }
    });
    var deskLineButton = body.querySelector('#hsnr-generate-desk-line');
    if (deskLineButton) deskLineButton.addEventListener('click', async function() {
      var error = body.querySelector('#hsnr-letter-error');
      deskLineButton.disabled = true;
      deskLineButton.textContent = '他正抬眼看過來……';
      error.hidden = true;
      try {
        await generateDeskLine();
        closePet();
      } catch (e) {
        var message = e && e.message ? e.message : '桌邊一句生成失敗。';
        savePetState({ deskLineError: message });
        error.textContent = message + ' 沒有送出任何聊天訊息。';
        error.hidden = false;
        deskLineButton.disabled = false;
        deskLineButton.textContent = '再試一次桌邊一句';
      }
    });
  }

  function openSettings() {
    var state = readPetState();
    var mode = letterMode(state);
    var sizePercent = petSizePercent(state);
    var sizeDevice = mobileLayout() ? '手機' : '桌面';
    var profiles = getConnectionProfiles();
    var profileOptions = '<option value="">請選擇酒館連線設定檔</option>' + profiles.map(function(profile) {
      var detail = [profile.name, profile.model || profile.api].filter(Boolean).join(' · ');
      return '<option value="' + escapeHtml(profile.id) + '"' + (String(state.letterProfileId || '') === profile.id ? ' selected' : '') + '>' + escapeHtml(detail) + '</option>';
    }).join('');
    var body = modalShell('相處設定', '設定跟著這個聊天走，不使用瀏覽器持久儲存，也不存放任何金鑰。');
    var bubbleEnabled = typeof state.bubbleEnabled === 'boolean' ? state.bubbleEnabled : dialogueConfig().defaults.bubbleEnabled !== false;
    var knockEnabled = typeof state.knockEnabled === 'boolean' ? state.knockEnabled : dialogueConfig().defaults.knockEnabled !== false;
    body.innerHTML =
      '<div class="hsnr-section-title"><h3>桌寵尺寸</h3><p>' + sizeDevice + '尺寸獨立保存</p></div>' +
      '<div class="hsnr-size-control"><label class="hsnr-size-label" for="hsnr-pet-size-range"><span>何思年在桌邊的大小</span><output id="hsnr-pet-size-value" for="hsnr-pet-size-range">' + sizePercent + '%</output></label><input id="hsnr-pet-size-range" type="range" min="60" max="180" step="10" value="' + sizePercent + '" aria-label="桌寵尺寸百分比"><div class="hsnr-size-buttons"><button class="hsnr-btn" id="hsnr-pet-size-minus" type="button" aria-label="縮小桌寵">－</button><button class="hsnr-btn" id="hsnr-pet-size-reset" type="button">重設 100%</button><button class="hsnr-btn" id="hsnr-pet-size-plus" type="button" aria-label="放大桌寵">＋</button></div><div class="hsnr-note">調整後立即預覽；範圍 60%～180%。手機與桌面各記一份，尺寸改變後仍會重新避開輸入框與螢幕邊界。</div></div>' +
      '<div class="hsnr-section-title"><h3>書信生成</h3><p>只改桌邊信紙，不新增聊天樓層</p></div>' +
      '<div class="hsnr-form"><div class="hsnr-field"><label for="hsnr-letter-mode">書信來源</label><select id="hsnr-letter-mode"><option value="local"' + (mode === 'local' ? ' selected' : '') + '>使用本地信件（零生成）</option><option value="current"' + (mode === 'current' ? ' selected' : '') + '>沿用目前酒館連線</option><option value="profile"' + (mode === 'profile' ? ' selected' : '') + '>指定副連線（Connection Profile）</option></select></div><div class="hsnr-field" id="hsnr-letter-profile-field"' + (mode === 'profile' ? '' : ' hidden') + '><label for="hsnr-letter-profile">副連線設定檔</label><select id="hsnr-letter-profile">' + profileOptions + '</select></div><div class="hsnr-note">副連線直接讀取酒館 Connection Profiles。請先在酒館建立連線設定檔；桌寵只記住 profile ID，不複製 API 網址或金鑰。' + (profiles.length ? '<br>目前讀到 ' + profiles.length + ' 個設定檔。' : '<br>目前沒有讀到設定檔；可先使用本地信件或目前酒館連線。') + '</div></div>' +
      '<div class="hsnr-section-title"><h3>桌邊互動</h3><p>自動內容一律零生成</p></div>' +
      '<div class="hsnr-actions"><button class="hsnr-btn" id="hsnr-bubbles">' + (bubbleEnabled ? '關閉情境氣泡' : '開啟情境氣泡') + '<small>時間、MVU、未讀信與停留狀態；不呼叫模型。</small></button><button class="hsnr-btn" id="hsnr-knock">' + (knockEnabled ? '關閉夜間敲窗' : '開啟夜間敲窗') + '<small>22:00～03:00 生效，至少間隔 45 分鐘。</small></button><button class="hsnr-btn" id="hsnr-night">' + (state.night === true ? '關閉夜間模式' : '開啟夜間模式') + '<small>降低桌寵亮度與飽和度。</small></button><button class="hsnr-btn" id="hsnr-reset-position">讓何思年回到右下角<small>只重設位置，不碰聊天或 MVU。</small></button></div>' +
      '<div class="hsnr-rule">桌邊氣泡、未讀提醒、藏信與敲窗只從角色設定檔和本聊天狀態挑句，不會暗中生成。只有妳在信件頁親手按「叫他在桌邊說一句」才會使用上方所選連線。已內嵌何思年 8×12／96 幀透明動畫圖集，信件語氣會映射到不同動作。</div>' +
      '<div class="hsnr-actions"><button class="hsnr-btn" data-page="letters">回到信紙</button><button class="hsnr-btn" data-page="home">返回</button></div>';
    bindActions(body);
    var sizeRange = body.querySelector('#hsnr-pet-size-range');
    var sizeValue = body.querySelector('#hsnr-pet-size-value');
    function updateSize(nextValue) {
      var next = applyPetSize(nextValue, true);
      sizeRange.value = String(next);
      sizeValue.textContent = next + '%';
      schedulePetLayout();
    }
    sizeRange.addEventListener('input', function(event) { updateSize(event.currentTarget.value); });
    body.querySelector('#hsnr-pet-size-minus').addEventListener('click', function() { updateSize(Number(sizeRange.value) - 10); });
    body.querySelector('#hsnr-pet-size-reset').addEventListener('click', function() { updateSize(100); });
    body.querySelector('#hsnr-pet-size-plus').addEventListener('click', function() { updateSize(Number(sizeRange.value) + 10); });
    body.querySelector('#hsnr-letter-mode').addEventListener('change', function(event) {
      var nextMode = event.currentTarget.value;
      savePetState({ letterMode: nextMode });
      var field = body.querySelector('#hsnr-letter-profile-field');
      field.hidden = nextMode !== 'profile';
    });
    body.querySelector('#hsnr-letter-profile').addEventListener('change', function(event) {
      savePetState({ letterProfileId: event.currentTarget.value });
    });
    body.querySelector('#hsnr-bubbles').addEventListener('click', function() { savePetState({ bubbleEnabled: !bubbleEnabled }); mountPet(); openSettings(); });
    body.querySelector('#hsnr-knock').addEventListener('click', function() { savePetState({ knockEnabled: !knockEnabled }); mountPet(); openSettings(); });
    body.querySelector('#hsnr-night').addEventListener('click', function() { savePetState({ night: state.night !== true }); mountPet(); openSettings(); });
    body.querySelector('#hsnr-reset-position').addEventListener('click', function() { savePetState({ x: null, y: null }); mountPet(); notify('何思年已回到右下角。', 'success'); });
  }

  function openDiagnostics() {
    var checks = [
      ['TavernHelper 按鈕事件', !!findApi('getButtonEvent') && !!findApi('eventOn')],
      ['MVU', !!findValue('Mvu')],
      ['聊天變量', !!findApi('getVariables') && !!findApi('insertOrAssignVariables')],
      ['酒館指令', !!findApi('triggerSlash')],
      ['書信副連線', getConnectionProfiles().length > 0],
      ['桌邊對話設定', dialogueConfig().schemaVersion !== 'fallback']
    ];
    var body = modalShell('哪裡斷線了', '紅燈不裝死；依照缺失項目重新啟用對應腳本或擴充。');
    body.innerHTML = '<div class="hsnr-vitals">' + checks.map(function(item) { return '<div class="hsnr-vital"><span>' + item[0] + '</span><strong style="color:' + (item[1] ? '#8eb49e' : '#d98270') + '">' + (item[1] ? '已連線' : '未連線') + '</strong></div>'; }).join('') + '</div><div class="hsnr-rule">若 MVU 未連線，確認 MVU 與 TavernHelper 已安裝並啟用。若副連線未讀到，先到 ST Connection Manager 建立 Connection Profile；卡片不保存網址或金鑰。</div><div class="hsnr-actions"><button class="hsnr-btn" data-page="diagnostics">重新偵測</button><button class="hsnr-btn" data-page="home">返回</button></div>';
    bindActions(body);
  }

  function showError(message) {
    var body = modalShell('連線沒有接好', message || '未知錯誤');
    body.innerHTML = '<div class="hsnr-error">' + escapeHtml(message || '未知錯誤') + '</div><div class="hsnr-actions"><button class="hsnr-btn" data-page="diagnostics">打開診斷</button><button class="hsnr-btn" data-page="home">返回</button></div>';
    bindActions(body);
  }

  function openPet(page) {
    if (!alive()) return false;
    if (page === 'status') openStatus();
    else if (page === 'letters') openLetters();
    else if (page === 'settings') openSettings();
    else if (page === 'diagnostics') openDiagnostics();
    else openHome();
    return true;
  }

  function registerSlashEntry() {
    try {
      var Parser = findValue('SlashCommandParser');
      var Command = findValue('SlashCommand');
      if (Parser && typeof Parser.addCommandObject === 'function' && Command && typeof Command.fromProps === 'function') {
        Parser.addCommandObject(Command.fromProps({
          name: 'hesinian', aliases: ['hsn-pet'],
          callback: function() { openPet('home'); return ''; },
          returns: 'empty string; opens Hesinian HTML without sending a message',
          helpString: '<div>開啟何思年桌寵與信件介面，不送出聊天訊息。</div>'
        }));
        return true;
      }
    } catch (e) { console.info('[何思年桌寵] modern slash registration skipped', e); }
    try {
      var legacy = findApi('registerSlashCommand');
      if (legacy) {
        legacy('jiangnan', function() { openPet('games'); return ''; }, ['hsnr-pet'], '開啟何思年 HTML，不送出訊息', true, true);
        return true;
      }
    } catch (e2) { console.info('[何思年桌寵] legacy slash registration skipped', e2); }
    return false;
  }

  async function setupQR(canRunCommand) {
    if (!canRunCommand) return;
    var slash = findApi('triggerSlash');
    if (!slash) return;
    try {
      var raw = await slash('/qr-set-list');
      var sets = [];
      try { sets = JSON.parse(raw || '[]'); } catch (e) {}
      if (!Array.isArray(sets)) sets = [];
            if (sets.indexOf(QR_SET) < 0) {
        await slash('/qr-set-create nosend=true ' + QR_SET);
        await slash('/qr-create set="' + QR_SET + '" label="💌 何思年" title="開啟何思年的桌寵與信件介面，不送訊息" /hesinian');
      }
      await slash('/qr-chat-set-on visible=true ' + QR_SET);
    } catch (e2) {
      console.info('[何思年桌寵] QR 自動建立失敗；TavernHelper 按鈕仍可使用', e2);
    }
  }

  function bindToolbar() {
    try {
      var on = findApi('eventOn'), getEvent = findApi('getButtonEvent');
      if (!on || !getEvent) throw new Error('button_api_unavailable');
      on(getEvent(BUTTON), function() { openPet('home'); });
    } catch (e) { notify('工具列按鈕沒有接上；桌面上的何思年仍可直接點。', 'warning'); }
  }

  var previous = globalThis[KEY];
  if (previous && typeof previous.destroy === 'function') {
    try { previous.destroy(); } catch (e) {}
  }
  var petApi = {
    token: token,
    assets: { spriteSheet: SPRITE_SHEET_URL, atlas: SPRITE_ATLAS },
    openPet: openPet,
    getConnectionProfiles: getConnectionProfiles,
    generateLetter: generateLetter,
    generateDeskLine: generateDeskLine,
    chooseContextWhisper: chooseContextWhisper,
    evaluateWhisper: evaluateWhisper,
    showWhisper: showWhisper,
    getUnlockedLetters: function() { return syncHiddenLetters().available.slice(); },
    openHiddenLetter: openHiddenLetter,
    setSizePercent: function(value) { var next = applyPetSize(value, true); schedulePetLayout(); return next; },
    setSpriteSequence: setSpriteSequence,
    close: closePet,
    destroy: function() {
      stopWhisperScheduler();
      clearPetLayout();
      cancelFrame(spriteAnimation.raf);
      spriteAnimation.raf = 0;
      var root = doc.getElementById(ROOT_ID), modal = doc.getElementById(MODAL_ID);
      if (root) root.remove(); if (modal) modal.remove();
    }
  };
  globalThis[KEY] = petApi;
  var publishGlobal = findApi('initializeGlobal');
  if (publishGlobal) publishGlobal(PET_GLOBAL, petApi);
  else {
    try { host[PET_GLOBAL] = petApi; } catch (e) {}
  }

  mountPet();
  bindToolbar();
  setupQR(registerSlashEntry());
  console.info('[何思年桌寵] v2.6 ready; dialogue=' + dialogueConfig().schemaVersion + '; auto-generation=false; letter-profiles=' + getConnectionProfiles().length + '; user-size=60..180; mobile-safe-area=true; embedded=96-frame-webp; qr=' + QR_SET);
});

entries.content:
@@preprocessing
<%_ /* ===== 何思年 全時期控制器 ===== */ _%>
<%_ /* 讀取時期與階段，依 時期×階段 載入行為條目 */ _%>
<%_ /* 核心不變/語言風格/版面規則/飲食跨時期/音樂動漫 = 常駐，不經控制器 */ _%>
<%_ /* 時期靜態內容（錨點/育幼院/大學/張榮/職場/八卦/飲食分段/告白被拒/親密指令/出軌引導/懷孕婚後/波賽頓前/波賽頓時代）= 開場連動管 */ _%>
<%_ if (typeof 時期 === 'undefined') var 時期 = getvar('stat_data.時期', { defaults: '成年' }); _%>
<%_ if (typeof 階段 === 'undefined') var 階段 = getvar('stat_data.階段', { defaults: '接近' }); _%>

<%_ /* ── 依 時期×階段 載入行為條目 ── */ _%>
<%_ switch (時期) {
  case '成年':
    switch (階段) {
      case '接近': _%>
<%- await getwi('成年_接近') %>
<%_     break;
      case '動搖': _%>
<%- await getwi('成年_動搖') %>
<%_     break;
      case '確認': _%>
<%- await getwi('成年_確認') %>
<%_     break;
    }
    break;
  case '學生':
    switch (階段) {
      case '同學': _%>
<%- await getwi('學生_同學') %>
<%_     break;
      case '曖昧': _%>
<%- await getwi('學生_曖昧') %>
<%_     break;
      case '分歧': _%>
<%- await getwi('學生_分歧') %>
<%_     break;
    }
    break;
  case '童年':
    switch (階段) {
      case '警戒': _%>
<%- await getwi('童年_警戒') %>
<%_     break;
      case '習慣': _%>
<%- await getwi('童年_習慣') %>
<%_     break;
      case '依附': _%>
<%- await getwi('童年_依附') %>
<%_     break;
    }
    break;
} _%>
